#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static char **results;
static int result_count;
static int result_capacity;

static void add_result(const char *path) {
    if (result_count == result_capacity) {
        result_capacity = (result_capacity == 0) ? 16 : result_capacity * 2;
        results = realloc(results, (size_t)result_capacity * sizeof(char *));
    }
    results[result_count] = malloc(strlen(path) + 1);
    strcpy(results[result_count], path);
    result_count++;
}

static void backtrack(int n, int open_count, int close_count,
                      char *path, int depth) {
    if (depth == 2 * n) {
        path[depth] = '\0';
        add_result(path);
        return;
    }

    if (open_count < n) {
        path[depth] = '(';
        backtrack(n, open_count + 1, close_count, path, depth + 1);
    }

    if (close_count < open_count) {
        path[depth] = ')';
        backtrack(n, open_count, close_count + 1, path, depth + 1);
    }
}

