class Solution {
    public List<String> generateParenthesis(int n) {
        List<String> result = new ArrayList<>();
        StringBuilder path = new StringBuilder(2 * n);
        backtrack(n, 0, 0, path, result);
        return result;
    }

    private void backtrack(int n, int openCount, int closeCount,
                            StringBuilder path, List<String> result) {
        if (path.length() == 2 * n) {
            result.add(path.toString());
            return;
        }

        if (openCount < n) {
            path.append('(');
            backtrack(n, openCount + 1, closeCount, path, result);
            path.deleteCharAt(path.length() - 1);
        }

        if (closeCount < openCount) {
            path.append(')');
            backtrack(n, openCount, closeCount + 1, path, result);
            path.deleteCharAt(path.length() - 1);
        }
    }
}

